export type LengthUnitId = 'mm' | 'cm' | 'm' | 'km' | 'in' | 'ft';

export type LengthUnitCategory =
  | 'metric'
  | 'imperial'
  | 'japanese'
  | 'astronomical'
  | 'custom'
  | (string & {});

export interface LengthUnitItem {
  id: LengthUnitId;
  name: string;
  symbol: string;
  toMeters: number;
  category: LengthUnitCategory;
  description: string;
}

export interface PresetItem {
  id: string;
  label: string;
  value: number;
  unit: LengthUnitId;
}

export interface HistoryRecord {
  id: string;
  inputValue: number;
  fromUnit: LengthUnitId;
  toUnit: LengthUnitId;
  resultValue: number;
  timestamp: string;
  createdAt: number;
}

import { LengthUnitId, LengthUnitItem, PresetItem } from './types';

export const LENGTH_UNITS: Record<LengthUnitId, LengthUnitItem> = {
  mm: {
    id: 'mm',
    name: 'ミリメートル',
    symbol: 'mm',
    toMeters: 0.001,
    category: 'metric',
    description: '1mの1,000分の1。精密機械や精密加工、紙の厚さ・寸法などで多用される極小単位です。',
  },
  cm: {
    id: 'cm',
    name: 'センチメートル',
    symbol: 'cm',
    toMeters: 0.01,
    category: 'metric',
    description: '1mの100分の1。文房具、衣類の寸法、身長など日常生活で最も広く親しまれている単位です。',
  },
  m: {
    id: 'm',
    name: 'メートル',
    symbol: 'm',
    toMeters: 1.0,
    category: 'metric',
    description: '国際単位系(SI)における長さの基本単位。光が真空中を約3億分の1秒に進む距離として定義されています。',
  },
  km: {
    id: 'km',
    name: 'キロメートル',
    symbol: 'km',
    toMeters: 1000.0,
    category: 'metric',
    description: '1mの1,000倍。道路の距離や都市間の隔たり、地理的なスケールを表すのに用いられます。',
  },
  in: {
    id: 'in',
    name: 'インチ',
    symbol: 'in',
    toMeters: 0.0254,
    category: 'imperial',
    description: 'ヤード・ポンド法の長さの単位。1インチは正確に25.4mm（2.54cm）と定義され、画面サイズやネジ規格に用いられます。',
  },
  ft: {
    id: 'ft',
    name: 'フィート',
    symbol: 'ft',
    toMeters: 0.3048,
    category: 'imperial',
    description: 'ヤード・ポンド法の長さの単位。1フィートは12インチ（正確に30.48cm）で、航空高度や建築などで現在も使われます。',
  },
};

export const LENGTH_UNIT_LIST: LengthUnitItem[] = [
  LENGTH_UNITS.mm,
  LENGTH_UNITS.cm,
  LENGTH_UNITS.m,
  LENGTH_UNITS.km,
  LENGTH_UNITS.in,
  LENGTH_UNITS.ft,
];

export const PRESETS: PresetItem[] = [
  { id: 'preset-a4', label: 'A4用紙長辺 (297mm)', value: 297, unit: 'mm' },
  { id: 'preset-ruler', label: '標準的な定規 (30cm)', value: 30, unit: 'cm' },
  { id: 'preset-meter', label: '1メートル (1m)', value: 1, unit: 'm' },
  { id: 'preset-height', label: '成人平均身長 (170cm)', value: 170, unit: 'cm' },
  { id: 'preset-inch', label: '1インチ (25.4mm)', value: 25.4, unit: 'mm' },
  { id: 'preset-shoe', label: '成人男性の足サイズ (10in)', value: 10, unit: 'in' },
  { id: 'preset-foot', label: '1フィート (30.48cm)', value: 30.48, unit: 'cm' },
  { id: 'preset-height-ft', label: '一般的な身長目安 (5.7ft)', value: 5.7, unit: 'ft' },
  { id: 'preset-marathon', label: 'フルマラソン (42.195km)', value: 42.195, unit: 'km' },
];

/**
 * 単位間の換算値を計算する関数
 */
export const convertLength = (
  value: number,
  fromUnit: LengthUnitId,
  toUnit: LengthUnitId
): number => {
  if (typeof value !== 'number' || !Number.isFinite(value)) return 0;
  if (fromUnit === toUnit) return value;

  const fromDef = LENGTH_UNITS[fromUnit];
  const toDef = LENGTH_UNITS[toUnit];

  if (!fromDef || !toDef || !toDef.toMeters || toDef.toMeters <= 0) return 0;

  const meters = value * fromDef.toMeters;
  const rawResult = meters / toDef.toMeters;

  if (!Number.isFinite(rawResult)) return 0;

  // 浮動小数点演算の丸め誤差を抑える処理
  return Math.round(rawResult * 1e12) / 1e12;
};

const numberFormatter = new Intl.NumberFormat('ja-JP', {
  maximumFractionDigits: 10,
  useGrouping: true,
});

/**
 * 有効桁数を適切に調整してフォーマットする関数
 */
export const formatLengthValue = (val: number): string => {
  if (typeof val !== 'number' || !Number.isFinite(val)) return '0';
  if (val === 0) return '0';

  const absVal = Math.abs(val);

  // 一般的な微細寸法（μmオーダーや0.001mmなど）も通常表記できるよう、極端に大きい・小さい場合のみ指数表記にする
  if (absVal >= 1e12 || absVal < 1e-9) {
    return val.toExponential(4);
  }

  return numberFormatter.format(val);
};

:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-border: #bfdbfe;
  --accent-color: #0d9488;
  --accent-light: #f0fdfa;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;
  --border-color: #e2e8f0;
  --border-focus: #1d4ed8;
  --focus-ring: rgba(37, 99, 235, 0.35);
  --success-color: #10b981;
  --success-bg: #ecfdf5;
  --danger-color: #ef4444;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* キーボード操作時のフォーカス視認性向上 */
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* アプリ全体のラッパー */
.app-wrapper {
  max-width: 860px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 24px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-main);
  letter-spacing: -0.025em;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-secondary);
  font-weight: 400;
}

/* モード切り替えタブ */
.mode-tabs {
  display: flex;
  background-color: #e2e8f0;
  padding: 4px;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
  gap: 4px;
}

.tab-btn {
  flex: 1;
  padding: 10px 16px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.tab-btn:hover:not(.tab-btn-active) {
  color: var(--text-main);
  background-color: rgba(255, 255, 255, 0.6);
}

.tab-btn-active {
  background-color: #ffffff;
  color: var(--primary-color);
  box-shadow: var(--shadow-sm);
}

/* メインカード */
.main-card {
  background-color: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  padding: 24px;
  margin-bottom: 24px;
}

/* 入力セクション */
.input-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 20px;
}

.input-group {
  display: flex;
  gap: 8px;
  align-items: stretch;
  position: relative;
}

.number-input {
  flex: 1;
  min-width: 0;
  font-size: 1.25rem;
  font-weight: 600;
  font-family: "SF Mono", Monaco, Inconsolata, "Fira Code", monospace;
  padding: 12px 16px;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-main);
  background-color: #ffffff;
  transition: var(--transition);
  outline: none;
}

.number-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.number-input:focus-visible {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--focus-ring);
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.number-input::placeholder {
  color: var(--text-muted);
  font-weight: 400;
}

.unit-select {
  padding: 12px 14px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: #f1f5f9;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  outline: none;
  transition: var(--transition);
  min-width: 140px;
}

.unit-select:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--focus-ring);
  background-color: #ffffff;
}

.unit-select:focus-visible {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--focus-ring);
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
  background-color: #ffffff;
}

.clear-btn {
  padding: 10px 14px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.clear-btn:hover {
  background-color: #e2e8f0;
  color: var(--danger-color);
}

.swap-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  padding: 10px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  background-color: #ffffff;
  color: var(--primary-color);
  cursor: pointer;
  transition: var(--transition);
  align-self: center;
  box-shadow: var(--shadow-sm);
}

.swap-btn:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  transform: rotate(180deg);
}

/* プリセットコンテナ */
.presets-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  background-color: #f8fafc;
  border-radius: var(--radius-md);
  border: 1px dashed var(--border-color);
  margin-bottom: 24px;
}

.presets-title {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.preset-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.preset-tag {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.preset-tag:hover {
  color: var(--primary-color);
  border-color: var(--primary-border);
  background-color: var(--primary-light);
  transform: translateY(-1px);
}

/* 一括変換グリッド結果 */
.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 14px;
}

.unit-card {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.unit-card:hover {
  border-color: var(--primary-border);
  box-shadow: var(--shadow-md);
}

.unit-card-active {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.2);
}

.unit-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.unit-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.unit-symbol-badge {
  font-size: 0.75rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background-color: #e2e8f0;
  color: var(--text-secondary);
  font-family: monospace;
}

.unit-card-active .unit-symbol-badge {
  background-color: var(--primary-color);
  color: #ffffff;
}

.unit-card-value {
  font-family: "SF Mono", Monaco, Inconsolata, "Fira Code", monospace;
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
  word-break: break-all;
  line-height: 1.3;
}

.unit-card-active .unit-card-value {
  color: var(--primary-color);
}

/* コピーボタン */
.copy-btn {
  align-self: flex-end;
  padding: 6px 10px;
  font-size: 0.8rem;
  font-weight: 600;
  border: 1px solid var(--border-color);
  background-color: #ffffff;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.copy-btn:hover {
  background-color: #f8fafc;
  color: var(--primary-color);
  border-color: var(--primary-border);
}

.copy-btn-copied {
  background-color: var(--success-bg) !important;
  color: var(--success-color) !important;
  border-color: var(--success-color) !important;
}

/* 個別変換モード用レイアウト */
.pair-converter-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pair-box {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background-color: #f8fafc;
  padding: 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.pair-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* 解説ボックス */
.explanation-box {
  margin-top: 16px;
  padding: 16px;
  background-color: var(--accent-light);
  border: 1px solid #ccfbf1;
  border-radius: var(--radius-md);
}

.explanation-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--accent-color);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.explanation-text {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* 履歴セクション */
.history-section {
  background-color: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  padding: 20px;
}

.history-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-color);
}

.history-header h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 6px;
}

.history-clear-btn {
  font-size: 0.8rem;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  text-decoration: underline;
  padding: 4px;
  transition: var(--transition);
}

.history-clear-btn:hover {
  color: var(--danger-color);
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 240px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) transparent;
}

/* Webkit系スクロールバーカスタマイズ */
.history-list::-webkit-scrollbar {
  width: 6px;
}

.history-list::-webkit-scrollbar-track {
  background: transparent;
}

.history-list::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: var(--radius-full);
}

.history-list::-webkit-scrollbar-thumb:hover {
  background-color: var(--text-muted);
}

.history-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background-color: #f8fafc;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  font-family: "SF Mono", Monaco, Inconsolata, "Fira Code", monospace;
  color: var(--text-secondary);
}

/* コピートースト通知 */
.toast-notification {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background-color: rgba(15, 23, 42, 0.9);
  color: #ffffff;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  backdrop-filter: blur(4px);
  z-index: 1000;
  pointer-events: none;
  animation: toastFadeInOut 2.5s ease forwards;
  display: flex;
  align-items: center;
  gap: 8px;
}

@keyframes toastFadeInOut {
  0% {
    opacity: 0;
    transform: translate(-50%, 10px);
  }
  15% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  85% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -10px);
  }
}

/* スマホ・タブレット用レスポンシブスタイル */
@media (max-width: 640px) {
  .app-wrapper {
    padding: 16px 12px 36px;
  }

  .header-title {
    font-size: 1.4rem;
  }

  .main-card {
    padding: 16px;
  }

  .input-group {
    flex-direction: column;
    gap: 10px;
  }

  .unit-select {
    width: 100%;
  }

  .pair-converter-container {
    gap: 12px;
  }

  .pair-box {
    padding: 14px 12px;
  }

  .pair-arrow {
    margin: 4px 0;
  }

  .swap-btn {
    width: 48px;
    height: 48px;
    min-width: 48px;
    min-height: 48px;
  }

  .results-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .preset-tags {
    gap: 6px;
  }

  .preset-tag {
    font-size: 0.8rem;
    padding: 5px 10px;
  }
}

import { useState, useRef, useEffect } from 'react';
import {
  Ruler,
  ArrowRightLeft,
  Copy,
  Check,
  RotateCcw,
  Sparkles,
  History,
  BookOpen,
  Info,
} from 'lucide-react';
import { LengthUnitId, HistoryRecord } from './types';
import {
  LENGTH_UNITS,
  LENGTH_UNIT_LIST,
  PRESETS,
  convertLength,
  formatLengthValue,
} from './constants';

type Mode = 'all' | 'pair';

export default function App() {
  const [mode, setMode] = useState<Mode>('all');
  const [inputValue, setInputValue] = useState<string>('1');
  const [baseUnit, setBaseUnit] = useState<LengthUnitId>('m');

  // 個別変換モード用
  const [targetUnit, setTargetUnit] = useState<LengthUnitId>('cm');

  // コピー状態とトースト
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const toastTimeoutRef = useRef<number | null>(null);
  const copyTimeoutRef = useRef<number | null>(null);

  // アンマウント時のタイマー解除
  useEffect(() => {
    return () => {
      if (toastTimeoutRef.current !== null) {
        clearTimeout(toastTimeoutRef.current);
      }
      if (copyTimeoutRef.current !== null) {
        clearTimeout(copyTimeoutRef.current);
      }
    };
  }, []);

  // 履歴初期データ
  const [historyList, setHistoryList] = useState<HistoryRecord[]>(() => [
    {
      id: 'init-1',
      inputValue: 1,
      fromUnit: 'm',
      toUnit: 'cm',
      resultValue: 100,
      timestamp: '12:00',
      createdAt: Date.now() - 60000,
    },
    {
      id: 'init-2',
      inputValue: 1,
      fromUnit: 'in',
      toUnit: 'mm',
      resultValue: 25.4,
      timestamp: '12:01',
      createdAt: Date.now(),
    },
  ]);

  const parsedValue = parseFloat(inputValue);
  const numericValue = isNaN(parsedValue) ? 0 : parsedValue;

  const showToast = (message: string) => {
    if (toastTimeoutRef.current !== null) {
      clearTimeout(toastTimeoutRef.current);
    }
    setToastMessage(message);
    toastTimeoutRef.current = window.setTimeout(() => {
      setToastMessage(null);
      toastTimeoutRef.current = null;
    }, 2500);
  };

  const handleCopy = (textToCopy: string, identifier: string) => {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard
        .writeText(textToCopy)
        .then(() => {
          if (copyTimeoutRef.current !== null) {
            clearTimeout(copyTimeoutRef.current);
          }
          setCopiedId(identifier);
          showToast(`「${textToCopy}」をコピーしました`);
          copyTimeoutRef.current = window.setTimeout(() => {
            setCopiedId(null);
            copyTimeoutRef.current = null;
          }, 1800);
        })
        .catch(() => {
          showToast('コピーに失敗しました');
        });
    } else {
      showToast('お使いの環境ではクリップボードへのアクセスが許可されていません');
    }
  };

  const addHistory = (from: LengthUnitId, to: LengthUnitId, inputVal: number, resultVal: number) => {
    const now = new Date();
    const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;

    setHistoryList((prev) => {
      const latest = prev[0];
      if (
        latest &&
        latest.fromUnit === from &&
        latest.toUnit === to &&
        latest.inputValue === inputVal &&
        latest.resultValue === resultVal
      ) {
        return prev;
      }

      const recordId =
        typeof crypto !== 'undefined' && crypto.randomUUID
          ? crypto.randomUUID()
          : `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;

      const newRecord: HistoryRecord = {
        id: recordId,
        inputValue: inputVal,
        fromUnit: from,
        toUnit: to,
        resultValue: resultVal,
        timestamp: timeStr,
        createdAt: Date.now(),
      };
      return [newRecord, ...prev.slice(0, 19)];
    });
  };

  const handlePresetSelect = (value: number, unit: LengthUnitId) => {
    setInputValue(value.toString());
    setBaseUnit(unit);
    // モードに関わらず整合性を持たせて履歴に追加
    const destUnit = unit === targetUnit ? (unit === 'cm' ? 'm' : 'cm') : targetUnit;
    const res = convertLength(value, unit, destUnit);
    addHistory(unit, destUnit, value, res);
  };

  const handleClear = () => {
    setInputValue('');
  };

  const handleSwapUnits = () => {
    const currentBase = baseUnit;
    const currentTarget = targetUnit;
    setBaseUnit(currentTarget);
    setTargetUnit(currentBase);

    if (inputValue !== '' && !isNaN(numericValue)) {
      const convertedVal = convertLength(numericValue, currentBase, currentTarget);
      setInputValue(Number(convertedVal.toFixed(8)).toString());
      addHistory(currentTarget, currentBase, convertedVal, numericValue);
    }
  };

  const handleBaseUnitChange = (unit: LengthUnitId) => {
    setBaseUnit(unit);
    if (inputValue !== '' && !isNaN(numericValue)) {
      const destUnit = unit === targetUnit ? (unit === 'cm' ? 'm' : 'cm') : targetUnit;
      const res = convertLength(numericValue, unit, destUnit);
      addHistory(unit, destUnit, numericValue, res);
    }
  };

  const handleTargetUnitChange = (unit: LengthUnitId) => {
    setTargetUnit(unit);
    if (inputValue !== '' && !isNaN(numericValue)) {
      const res = convertLength(numericValue, baseUnit, unit);
      addHistory(baseUnit, unit, numericValue, res);
    }
  };

  const handlePairInputCommit = () => {
    if (inputValue !== '' && !isNaN(numericValue)) {
      const res = convertLength(numericValue, baseUnit, targetUnit);
      addHistory(baseUnit, targetUnit, numericValue, res);
    }
  };

  const clearHistory = () => {
    setHistoryList([]);
  };

  const pairResult = convertLength(numericValue, baseUnit, targetUnit);
  const formattedPairResult = inputValue === '' ? '-' : formatLengthValue(pairResult);

  return (
    <div className="app-wrapper">
      {/* トースト通知 */}
      {toastMessage && (
        <div className="toast-notification">
          <Check size={16} />
          <span>{toastMessage}</span>
        </div>
      )}

      {/* ヘッダー */}
      <header className="app-header">
        <h1 className="header-title">
          <Ruler size={30} color="#2563eb" />
          長さの単位換算ツール
        </h1>
        <p className="header-subtitle">
          mm・cm・m・km・インチ・フィートを瞬時に高精度相互変換
        </p>
      </header>

      {/* モード切り替えタブ */}
      <div className="mode-tabs">
        <button
          type="button"
          className={`tab-btn ${mode === 'all' ? 'tab-btn-active' : ''}`}
          onClick={() => setMode('all')}
        >
          <Sparkles size={18} />
          一括全単位換算
        </button>
        <button
          type="button"
          className={`tab-btn ${mode === 'pair' ? 'tab-btn-active' : ''}`}
          onClick={() => setMode('pair')}
        >
          <ArrowRightLeft size={18} />
          個別2単位変換
        </button>
      </div>

      {/* 身近な長さプリセット */}
      <div className="presets-container">
        <div className="presets-title">
          <Sparkles size={16} /> 身近な長さプリセット
        </div>
        <div className="preset-tags">
          {PRESETS.map((preset) => (
            <button
              key={preset.id}
              type="button"
              className="preset-tag"
              onClick={() => handlePresetSelect(preset.value, preset.unit)}
            >
              {preset.label}
            </button>
          ))}
        </div>
      </div>

      {/* メインカード */}
      <div className="main-card">
        {mode === 'all' ? (
          /* 一括全単位換算モード */
          <div>
            <div className="input-section">
              <div className="input-group">
                <input
                  type="number"
                  step="any"
                  className="number-input"
                  placeholder="数値を入力..."
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                />
                <select
                  className="unit-select"
                  value={baseUnit}
                  onChange={(e) => handleBaseUnitChange(e.target.value as LengthUnitId)}
                >
                  {LENGTH_UNIT_LIST.map((unit) => (
                    <option key={unit.id} value={unit.id}>
                      {unit.name} ({unit.symbol})
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  className="clear-btn"
                  onClick={handleClear}
                  title="入力をクリア"
                >
                  クリア
                </button>
              </div>
            </div>

            {/* 結果グリッド表示 */}
            <div className="results-grid">
              {LENGTH_UNIT_LIST.map((unit) => {
                const isCurrentBase = unit.id === baseUnit;
                const converted = isCurrentBase
                  ? numericValue
                  : convertLength(numericValue, baseUnit, unit.id);
                const formatted = inputValue === '' ? '-' : formatLengthValue(converted);
                const displayFull = inputValue === '' ? '-' : `${formatted} ${unit.symbol}`;
                const isCopied = copiedId === unit.id;

                return (
                  <div
                    key={unit.id}
                    className={`unit-card ${isCurrentBase ? 'unit-card-active' : ''}`}
                  >
                    <div className="unit-card-header">
                      <span className="unit-name">{unit.name}</span>
                      <span className="unit-symbol-badge">{unit.symbol}</span>
                    </div>

                    <div className="unit-card-value">
                      {formatted}
                    </div>

                    <button
                      type="button"
                      className={`copy-btn ${isCopied ? 'copy-btn-copied' : ''}`}
                      onClick={() => handleCopy(displayFull, unit.id)}
                    >
                      {isCopied ? (
                        <>
                          <Check size={14} /> コピー済
                        </>
                      ) : (
                        <>
                          <Copy size={14} /> コピー
                        </>
                      )}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          /* 個別2単位変換モード */
          <div className="pair-converter-container">
            {/* 変換元 */}
            <div className="pair-box">
              <span className="unit-name">変換元の値と単位</span>
              <div className="input-group">
                <input
                  type="number"
                  step="any"
                  className="number-input"
                  placeholder="数値を入力..."
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onBlur={handlePairInputCommit}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      handlePairInputCommit();
                    }
                  }}
                />
                <select
                  className="unit-select"
                  value={baseUnit}
                  onChange={(e) => handleBaseUnitChange(e.target.value as LengthUnitId)}
                >
                  {LENGTH_UNIT_LIST.map((unit) => (
                    <option key={unit.id} value={unit.id}>
                      {unit.name} ({unit.symbol})
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  className="clear-btn"
                  onClick={handleClear}
                >
                  クリア
                </button>
              </div>
            </div>

            {/* スワップボタン */}
            <div className="pair-arrow">
              <button
                type="button"
                className="swap-btn"
                onClick={handleSwapUnits}
                title="変換元と変換先を入れ替える"
              >
                <ArrowRightLeft size={18} />
              </button>
            </div>

            {/* 変換先 */}
            <div className="pair-box">
              <span className="unit-name">変換先の値と単位</span>
              <div className="input-group">
                <input
                  type="text"
                  readOnly
                  className="number-input"
                  value={formattedPairResult}
                  style={{ backgroundColor: '#f8fafc' }}
                />
                <select
                  className="unit-select"
                  value={targetUnit}
                  onChange={(e) => handleTargetUnitChange(e.target.value as LengthUnitId)}
                >
                  {LENGTH_UNIT_LIST.map((unit) => (
                    <option key={unit.id} value={unit.id}>
                      {unit.name} ({unit.symbol})
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  className={`copy-btn ${copiedId === 'pair-res' ? 'copy-btn-copied' : ''}`}
                  onClick={() =>
                    handleCopy(
                      inputValue === ''
                        ? '-'
                        : `${formattedPairResult} ${LENGTH_UNITS[targetUnit].symbol}`,
                      'pair-res'
                    )
                  }
                  style={{ alignSelf: 'stretch' }}
                >
                  {copiedId === 'pair-res' ? (
                    <>
                      <Check size={14} /> コピー済
                    </>
                  ) : (
                    <>
                      <Copy size={14} /> コピー
                    </>
                  )}
                </button>
              </div>
            </div>

            {/* 相互変換の解説 */}
            <div className="explanation-box">
              <div className="explanation-title">
                <BookOpen size={16} />
                <span>
                  1 {LENGTH_UNITS[baseUnit].symbol} ={' '}
                  {formatLengthValue(convertLength(1, baseUnit, targetUnit))}{' '}
                  {LENGTH_UNITS[targetUnit].symbol}
                </span>
              </div>
              <div className="explanation-text">
                {LENGTH_UNITS[baseUnit].name} ({LENGTH_UNITS[baseUnit].symbol}):{' '}
                {LENGTH_UNITS[baseUnit].description}
                <br />
                {LENGTH_UNITS[targetUnit].name} ({LENGTH_UNITS[targetUnit].symbol}):{' '}
                {LENGTH_UNITS[targetUnit].description}
              </div>
            </div>
          </div>
        )}

        {/* 基準単位の解説（一括変換時） */}
        {mode === 'all' && (
          <div className="explanation-box">
            <div className="explanation-title">
              <Info size={16} />
              <span>選択中の単位: {LENGTH_UNITS[baseUnit].name} ({LENGTH_UNITS[baseUnit].symbol})</span>
            </div>
            <div className="explanation-text">
              {LENGTH_UNITS[baseUnit].description}
            </div>
          </div>
        )}
      </div>

      {/* 履歴セクション */}
      <section className="history-section">
        <div className="history-header">
          <h3>
            <History size={18} />
            換算履歴
          </h3>
          {historyList.length > 0 && (
            <button
              type="button"
              className="history-clear-btn"
              onClick={clearHistory}
            >
              <RotateCcw size={12} style={{ display: 'inline', marginRight: 4 }} />
              履歴を消去
            </button>
          )}
        </div>

        {historyList.length === 0 ? (
          <div style={{ color: 'var(--text-muted)', fontSize: '0.85rem', textAlign: 'center', padding: '12px' }}>
            履歴はまだありません
          </div>
        ) : (
          <div className="history-list">
            {historyList.map((item) => (
              <div key={item.id} className="history-item">
                <span>
                  {formatLengthValue(item.inputValue)} {item.fromUnit} ={' '}
                  <strong style={{ color: 'var(--primary-color)' }}>
                    {formatLengthValue(item.resultValue)} {item.toUnit}
                  </strong>
                </span>
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                  {item.timestamp}
                </span>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
